    let currentLang = localStorage.getItem('selectedLang') || 'hi';
    const langSelect = document.getElementById('langSelect');

    function applyLanguage(lang) {
        currentLang = lang;
        localStorage.setItem('selectedLang', lang);
        if (langSelect) langSelect.value = lang;

        const langDict = translations[lang] || translations.hi;
        document.querySelectorAll('[data-i18n]').forEach(el => {
            const key = el.getAttribute('data-i18n');
            if (langDict[key]) {
                el.innerText = langDict[key];
            }
        });
    }

    if (langSelect) {
        langSelect.value = currentLang;
        langSelect.addEventListener('change', (e) => {
            applyLanguage(e.target.value);
        });
    }

    applyLanguage(currentLang);

    // ----------------------------------------------------------------------
    // 2. PWA Service Worker & Install Prompt
    // ----------------------------------------------------------------------
    let deferredPrompt = null;
    const pwaInstallBanner = document.getElementById('pwaInstallBanner');
    const pwaInstallBtn = document.getElementById('pwaInstallBtn');

    if ('serviceWorker' in navigator) {
        navigator.serviceWorker.register('./sw.js')
            .then(reg => console.log('Service Worker registered:', reg.scope))
            .catch(err => console.error('Service Worker registration failed:', err));
    }

    window.addEventListener('beforeinstallprompt', (e) => {
        e.preventDefault();
        deferredPrompt = e;
        if (pwaInstallBanner) pwaInstallBanner.classList.remove('hidden');
    });

    if (pwaInstallBtn) {
        pwaInstallBtn.addEventListener('click', async () => {
            if (deferredPrompt) {
                deferredPrompt.prompt();
                const { outcome } = await deferredPrompt.userChoice;
                if (outcome === 'accepted') console.log('PWA installation accepted');
                deferredPrompt = null;
                pwaInstallBanner.classList.add('hidden');
            }
        });
    }

    // ----------------------------------------------------------------------
    // 3. Background Starfield Canvas
    // ----------------------------------------------------------------------
    const canvas = document.getElementById('starsCanvas');
    const ctx = canvas.getContext('2d');
    let stars = [];

    function initCanvas() {
        canvas.width = window.innerWidth;
        canvas.height = window.innerHeight;
        stars = [];
        for (let i = 0; i < 140; i++) {
            stars.push({
                x: Math.random() * canvas.width,
                y: Math.random() * canvas.height,
                radius: Math.random() * 1.4 + 0.5,
                alpha: Math.random(),
                speed: Math.random() * 0.015 + 0.005
            });
        }
    }

    function animateStars() {
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        stars.forEach(star => {
            star.alpha += star.speed;
            if (star.alpha > 1 || star.alpha < 0) star.speed = -star.speed;
            ctx.fillStyle = `rgba(223, 172, 108, ${Math.abs(star.alpha)})`;
            ctx.beginPath();
            ctx.arc(star.x, star.y, star.radius, 0, Math.PI * 2);
            ctx.fill();
        });
        requestAnimationFrame(animateStars);
    }

    window.addEventListener('resize', initCanvas);
    initCanvas();
    animateStars();

    // ----------------------------------------------------------------------
    // 4. Navigation System (Desktop & Mobile Sync)
    // ----------------------------------------------------------------------
    const desktopNavBtns = document.querySelectorAll('.desktop-nav .nav-btn');
    const mobileNavBtns = document.querySelectorAll('.mobile-bottom-nav .mobile-nav-btn');
    const tabSections = document.querySelectorAll('.tab-section');

    function switchTab(targetTab) {
        desktopNavBtns.forEach(b => {
            if (b.getAttribute('data-tab') === targetTab) b.classList.add('active');
            else b.classList.remove('active');
        });

        mobileNavBtns.forEach(b => {
            if (b.getAttribute('data-tab') === targetTab) b.classList.add('active');
            else b.classList.remove('active');
        });

        tabSections.forEach(s => s.classList.remove('active'));
        tabSections.forEach(s => s.classList.add('hidden'));

        const activeSection = document.getElementById(`${targetTab}Section`);
        if (activeSection) {
            activeSection.classList.remove('hidden');
            activeSection.classList.add('active');
        }

        if (targetTab === 'history') {
            renderHistoryList();
        }
    }

    desktopNavBtns.forEach(btn => btn.addEventListener('click', () => switchTab(btn.getAttribute('data-tab'))));
    mobileNavBtns.forEach(btn => btn.addEventListener('click', () => switchTab(btn.getAttribute('data-tab'))));

    // ----------------------------------------------------------------------
    // 5. Palmistry Scanner Engine
    // ----------------------------------------------------------------------
    const startCamBtn = document.getElementById('startCamBtn');
    const captureScanBtn = document.getElementById('captureScanBtn');
    const uploadInput = document.getElementById('uploadInput');
    const webcamFeed = document.getElementById('webcamFeed');
    const previewImage = document.getElementById('previewImage');
    const palmCanvas = document.getElementById('palmOverlayCanvas');
    const pCtx = palmCanvas.getContext('2d');
    const scannerPlaceholder = document.getElementById('scannerPlaceholder');
    const scanLaser = document.getElementById('scanLaser');

    const readingLoading = document.getElementById('readingLoading');
    const readingResults = document.getElementById('readingResults');
    const emptyPlaceholder = document.getElementById('emptyResultPlaceholder');
    const readingTextContent = document.getElementById('readingTextContent');

    let isCameraActive = false;

    startCamBtn.addEventListener('click', async () => {
        try {
            const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: "environment" } });
            webcamFeed.srcObject = stream;
            webcamFeed.classList.remove('hidden');
            previewImage.classList.add('hidden');
            scannerPlaceholder.classList.add('hidden');
            captureScanBtn.classList.remove('hidden');
            startCamBtn.classList.add('hidden');
            isCameraActive = true;
            resizePalmCanvas();
        } catch (err) {
            alert(currentLang === 'en' ? 'Unable to start camera. Please upload a photo.' : 'कैमरा शुरू करने में असमर्थ। कृपया फोटो अपलोड करें।');
        }
    });

    uploadInput.addEventListener('change', (e) => {
        const file = e.target.files[0];
        if (file) {
            const reader = new FileReader();
            reader.onload = (evt) => {
                previewImage.src = evt.target.result;
                previewImage.classList.remove('hidden');
                webcamFeed.classList.add('hidden');
                scannerPlaceholder.classList.add('hidden');
                captureScanBtn.classList.remove('hidden');

                if (isCameraActive && webcamFeed.srcObject) {
                    webcamFeed.srcObject.getTracks().forEach(track => track.stop());
                    isCameraActive = false;
                }

                previewImage.onload = () => resizePalmCanvas();
            };
            reader.readAsDataURL(file);
        }
    });

    function resizePalmCanvas() {
        const viewport = document.getElementById('scannerViewport');
        palmCanvas.width = viewport.clientWidth;
        palmCanvas.height = viewport.clientHeight;
    }

    function drawGlowingPalmOverlay() {
        resizePalmCanvas();
        const w = palmCanvas.width;
        const h = palmCanvas.height;
        pCtx.clearRect(0, 0, w, h);

        pCtx.strokeStyle = '#DFAC6C';
        pCtx.lineWidth = 4;
        pCtx.shadowColor = '#DFAC6C';
        pCtx.shadowBlur = 12;
        pCtx.beginPath();
        pCtx.moveTo(w * 0.25, h * 0.42);
        pCtx.quadraticCurveTo(w * 0.5, h * 0.35, w * 0.8, h * 0.32);
        pCtx.stroke();

        pCtx.strokeStyle = '#6D28D9';
        pCtx.lineWidth = 4;
        pCtx.shadowColor = '#6D28D9';
        pCtx.shadowBlur = 12;
        pCtx.beginPath();
        pCtx.moveTo(w * 0.22, h * 0.48);
        pCtx.quadraticCurveTo(w * 0.5, h * 0.48, w * 0.75, h * 0.58);
        pCtx.stroke();

        pCtx.strokeStyle = '#10B981';
        pCtx.lineWidth = 4;
        pCtx.shadowColor = '#10B981';
        pCtx.shadowBlur = 12;
        pCtx.beginPath();
        pCtx.moveTo(w * 0.22, h * 0.48);
        pCtx.quadraticCurveTo(w * 0.38, h * 0.65, w * 0.3, h * 0.85);
        pCtx.stroke();

        pCtx.strokeStyle = '#F7E2BD';
        pCtx.lineWidth = 3.5;
        pCtx.shadowColor = '#F7E2BD';
        pCtx.shadowBlur = 12;
        pCtx.beginPath();
        pCtx.moveTo(w * 0.52, h * 0.82);
        pCtx.lineTo(w * 0.5, h * 0.38);
        pCtx.stroke();
    }

    captureScanBtn.addEventListener('click', () => {
        scanLaser.classList.remove('hidden');
        emptyPlaceholder.classList.add('hidden');
        readingResults.classList.add('hidden');
        readingLoading.classList.remove('hidden');

        drawGlowingPalmOverlay();

        setTimeout(() => {
            scanLaser.classList.add('hidden');
            readingLoading.classList.add('hidden');
            readingResults.classList.remove('hidden');

            const readingText = generateShastraReading(currentLang);
            readingTextContent.innerHTML = readingText;
            window.latestReadingText = readingText;
        }, 2200);
    });

    function generateShastraReading(lang) {
        if (lang === 'en') {
            return `
                <h3>📌 Scripture-Grounded Astrological Reading</h3>
                <p><em>(Grounded in Cheiro Palmistry, Samudrik Shastra & Vrihad Hastrekha Shastra)</em></p>
                <h3>✋ Detailed Palm Lines & Mounts Analysis:</h3>
                <ul>
                    <li><strong>Heart Line:</strong> Deep, clear line reaching Mount of Jupiter. Indicates emotional strength & loyalty.</li>
                    <li><strong>Head Line:</strong> Straight line showing high logical intellect and decisive vision.</li>
                    <li><strong>Life Line:</strong> Smooth curvature symbolizing vitality, longevity and positive energy.</li>
                    <li><strong>Fate Line & Mounts:</strong> Strong Fate Line leading to Saturn mount, creating a Raj-Yoga for career growth.</li>
                </ul>
                <h3>🔮 Remedial Guidance:</h3>
                <ul>
                    <li>Offer water with turmeric to the Sun every Thursday.</li>
                    <li>Recite Hanuman Chalisa on Tuesdays for Mars alignment.</li>
                </ul>
            `;
        }
        return `
            <h3>📌 शास्त्र-आधारित हस्तरेखा एवं फलकथन विश्लेषण</h3>
            <p><em>(कीरो हस्तरेखा शास्त्र, सामुद्रिक शास्त्र, वृहद् हस्तरेखा शास्त्र एवं सामुद्रिक हस्तरेखा विज्ञान पर आधारित)</em></p>
            <h3>✋ मुख्य रेखाओं एवं पर्वतों का विस्तृत विश्लेषण:</h3>
            <ul>
                <li><strong>हृदय रेखा (Heart Line):</strong> कीरो हस्तरेखा शास्त्र के अनुसार आपकी हृदय रेखा अत्यंत स्पष्ट, गहरी एवं गुरु पर्वत तक विस्तृत है। यह आपके उच्च भावनात्मक संतुलन का प्रतीक है।</li>
                <li><strong>मस्तिष्क रेखा (Head Line):</strong> आपकी मस्तिष्क रेखा तीव्र तार्किक क्षमता एवं त्वरित निर्णय शक्ति को दर्शाती है।</li>
                <li><strong>जीवन रेखा (Life Line):</strong> सामुद्रिक शास्त्र के अनुसार जीवन रेखा की गोलाई दीर्घायु एवं ऊर्जा शक्ति का संकेत देती है।</li>
                <li><strong>भाग्य रेखा एवं पर्वत (Fate Line):</strong> भाग्य रेखा शनि पर्वत की ओर अग्रसर है, जो राज-योग एवं व्यावसायिक सफलता का योग बनाती है।</li>
            </ul>
            <h3>💡 शास्त्र-सम्मत अचूक उपाय:</h3>
            <ul>
                <li>प्रत्येक गुरुवार को जल में हल्दी मिलाकर सूर्य देव को अर्घ्य दें।</li>
                <li>मंगलवार के दिन हनुमान चालीसा का पाठ करें।</li>
            </ul>
        `;
    }

    document.getElementById('saveReadingBtn').addEventListener('click', () => {
        if (!window.latestReadingText) return;
        const history = JSON.parse(localStorage.getItem('palmistryHistory') || '[]');
        const newReading = {
            id: Date.now(),
            date: new Date().toLocaleDateString(currentLang === 'en' ? 'en-US' : 'hi-IN', { day: 'numeric', month: 'short', year: 'numeric' }),
            text: window.latestReadingText
        };
        history.unshift(newReading);
        localStorage.setItem('palmistryHistory', JSON.stringify(history));
        alert(currentLang === 'en' ? 'Reading saved to history!' : 'फलकथन आपके इतिहास में सुरक्षित कर लिया गया है!');
    });

    document.getElementById('exportPdfBtn').addEventListener('click', () => {
        if (!window.latestReadingText) return;
        const element = document.createElement('div');
        element.style.padding = '30px';
        element.style.color = '#1A0A2E';
        element.style.fontFamily = 'serif';
        element.innerHTML = `
            <h1 style="color: #6D28D9; text-align: center;">AI Palmistry Pro - Astrological Report</h1>
            <hr style="border: 1px solid #DFAC6C; margin: 15px 0;">
            ${window.latestReadingText}
            <br><hr>
            <p style="text-align: center; font-size: 12px; color: #666;">© 2026 AI Palmistry Pro Multilingual App.</p>
        `;
        html2pdf().set({
            margin: 10,
            filename: 'AI_Palmistry_Pro_Report.pdf',
            image: { type: 'jpeg', quality: 0.98 },
            html2canvas: { scale: 2 },
            jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' }
        }).from(element).save();
    });

    // Kundli Section
    const kundliForm = document.getElementById('kundliForm');
    kundliForm.addEventListener('submit', (e) => {
        e.preventDefault();
        const kName = document.getElementById('kName').value;
        const kDob = document.getElementById('kDob').value;

        document.getElementById('kundliAnalysisText').innerHTML = `
            <h3><i class="fa-solid fa-gem"></i> ${kName} (${kDob}):</h3>
            <ul>
                <li><strong>Lagna:</strong> Aries Lagna (Mars Lordship). Strong energy & leadership.</li>
                <li><strong>Raj-Yoga:</strong> Sun & Jupiter confluence in 1st house creates Raj-Yoga.</li>
            </ul>
        `;
    });

    // Tarot Section
    const tarotDeck = document.getElementById('tarotDeck');
    const tarotCardsData = [
        { name: "The Magician" },
        { name: "The Sun" },
        { name: "Wheel of Fortune" },
        { name: "The Star" },
        { name: "The Empress" }
    ];

    function buildTarotDeck() {
        tarotDeck.innerHTML = '';
        for (let i = 0; i < 5; i++) {
            const cardEl = document.createElement('div');
            cardEl.className = 'tarot-card-item';
            cardEl.innerHTML = `
                <div class="tarot-card-inner">
                    <div class="tarot-card-back">
                        <i class="fa-solid fa-eye"></i>
                        <p>Card ${i + 1}</p>
                    </div>
                    <div class="tarot-card-front">
                        <i class="fa-solid fa-sun-plant-wilt fa-2x"></i>
                        <h4>${tarotCardsData[i].name}</h4>
                    </div>
                </div>
            `;
            cardEl.addEventListener('click', () => {
                cardEl.classList.toggle('flipped');
                document.getElementById('tarotOutput').classList.remove('hidden');
                document.getElementById('tarotTextResult').innerHTML = `
                    <h3>🔮 Tarot Guidance:</h3>
                    <p>Positive cosmic alignment. Trust your inner intuition.</p>
                `;
            });
            tarotDeck.appendChild(cardEl);
        }
    }
    buildTarotDeck();

    // Numerology Section
    const calcNumerologyBtn = document.getElementById('calcNumerologyBtn');
    calcNumerologyBtn.addEventListener('click', () => {
        const dobStr = document.getElementById('numDobInput').value;
        if (!dobStr) return;

        const dateParts = dobStr.split('-');
        const day = parseInt(dateParts[2], 10);

        let mulank = day;
        while (mulank > 9) mulank = Math.floor(mulank / 10) + (mulank % 10);

        let digitsSum = dobStr.replace(/-/g, '').split('').reduce((acc, d) => acc + parseInt(d, 10), 0);
        let bhagyank = digitsSum;
        while (bhagyank > 9) bhagyank = Math.floor(bhagyank / 10) + (bhagyank % 10);

        document.getElementById('mulankVal').innerText = mulank;
        document.getElementById('bhagyankVal').innerText = bhagyank;

        document.getElementById('numerologyText').innerHTML = `
            <h3><i class="fa-solid fa-star"></i> Mulank ${mulank} & Bhagyank ${bhagyank}:</h3>
            <p>Independent, intellectual & visionary personality.</p>
        `;
    });
    calcNumerologyBtn.click();

    // History Section
    function renderHistoryList() {
        const historyList = document.getElementById('historyList');
        const history = JSON.parse(localStorage.getItem('palmistryHistory') || '[]');

        if (history.length === 0) {
            historyList.innerHTML = '<p class="empty-placeholder">No saved history found.</p>';
            return;
        }

        historyList.innerHTML = history.map(item => `
            <div class="history-item-card">
                <div class="history-item-header">
                    <span><i class="fa-solid fa-calendar"></i> ${item.date}</span>
                    <button onclick="deleteHistoryItem(${item.id})" class="btn btn-danger-sm"><i class="fa-solid fa-xmark"></i></button>
                </div>
                <div class="history-item-body">${item.text}</div>
            </div>
        `).join('');
    }

    window.deleteHistoryItem = function(id) {
        let history = JSON.parse(localStorage.getItem('palmistryHistory') || '[]');
        history = history.filter(item => item.id !== id);
        localStorage.setItem('palmistryHistory', JSON.stringify(history));
        renderHistoryList();
    };

    document.getElementById('clearHistoryBtn').addEventListener('click', () => {
        if (confirm(currentLang === 'en' ? 'Clear all reading history?' : 'क्या आप पूरा इतिहास साफ़ करना चाहते हैं?')) {
            localStorage.removeItem('palmistryHistory');
            renderHistoryList();
        }
    });

});

/* ==========================================================================
   AI Palmistry Pro - Royal Midnight & Antique Gold Classy Design System
   ========================================================================== */

@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,600;0,700;1,400&family=Outfit:wght@300;400;500;600;700&family=Noto+Serif+Devanagari:wght@400;500;600;700&display=swap');

:root {
    --bg-dark: #0A0616;
    --royal-indigo: #130B27;
    --card-bg: rgba(23, 14, 46, 0.75);
    --card-border: rgba(223, 172, 108, 0.22);
    --card-border-glow: rgba(223, 172, 108, 0.45);

    /* Antique Gold Palette */
    --gold-primary: #DFAC6C;
    --gold-light: #F7E2BD;
    --gold-dark: #A67537;
    --gold-gradient: linear-gradient(135deg, #F7E2BD 0%, #DFAC6C 50%, #B88544 100%);
    --gold-glow: rgba(223, 172, 108, 0.25);

    /* Deep Velvet Violet Accents */
    --velvet-violet: #6D28D9;
    --velvet-glow: rgba(109, 40, 217, 0.35);

    --soft-white: #F8FAFC;
    --text-muted: #94A3B8;
    --error-red: #F87171;

    --radius-lg: 20px;
    --radius-md: 14px;
    --radius-sm: 8px;

    --font-serif: 'Playfair Display', serif;
    --font-heading: 'Outfit', sans-serif;
    --font-body: 'Noto Serif Devanagari', 'Outfit', serif;

    --transition-smooth: all 0.35s cubic-bezier(0.16, 1, 0.3, 1);
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
    font-family: var(--font-body);
    -webkit-tap-highlight-color: transparent;
}

body {
    background: radial-gradient(circle at 50% 0%, #1D103A 0%, #0A0616 70%);
    color: var(--soft-white);
    min-height: 100vh;
    overflow-x: hidden;
    position: relative;
    padding-bottom: 75px;
}

/* Background Cosmic Canvas */
#starsCanvas {
    position: fixed;
    top: 0;
    left: 0;
    width: 100vw;
    height: 100vh;
    z-index: 0;
    pointer-events: none;
    opacity: 0.85;
}

/* PWA Install Banner */
.pwa-install-banner {
    position: fixed;
    top: 14px;
    left: 50%;
    transform: translateX(-50%);
    width: 92%;
    max-width: 520px;
    background: rgba(19, 11, 39, 0.95);
    backdrop-filter: blur(24px);
    border: 1px solid var(--gold-primary);
    border-radius: var(--radius-md);
    padding: 12px 20px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    z-index: 9999;
    box-shadow: 0 12px 35px rgba(0, 0, 0, 0.7), 0 0 20px var(--gold-glow);
    animation: slideDown 0.5s cubic-bezier(0.16, 1, 0.3, 1);
}

@keyframes slideDown {
    from { transform: translate(-50%, -40px); opacity: 0; }
    to { transform: translate(-50%, 0); opacity: 1; }
}

.pwa-install-info {
    display: flex;
    align-items: center;
    gap: 14px;
}

.pwa-icon {
    font-size: 1.8rem;
    color: var(--gold-primary);
}

.pwa-install-info strong {
    font-family: var(--font-heading);
    font-size: 0.95rem;
    color: var(--soft-white);
}

.pwa-install-info span {
    font-size: 0.78rem;
    color: var(--text-muted);
}

/* App Main Layout Container */
#appContainer {
    position: relative;
    z-index: 1;
    max-width: 1280px;
    margin: 0 auto;
    padding: 16px 16px;
    display: flex;
    flex-direction: column;
    min-height: 100vh;
}

/* ALWAYS VISIBLE TOP BAR */
.top-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 10px 18px;
    background: rgba(19, 11, 39, 0.9);
    backdrop-filter: blur(24px);
    border: 1.5px solid var(--gold-primary);
    border-radius: var(--radius-md);
    margin-bottom: 16px;
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.5), 0 0 15px var(--gold-glow);
}

.header-logo-sm {
    display: flex;
    align-items: center;
    gap: 8px;
}

.logo-icon-sm {
    font-size: 1.3rem;
    color: var(--gold-primary);
}

.logo-title-sm {
    font-family: var(--font-serif);
    font-size: 1.15rem;
    font-weight: 700;
    background: var(--gold-gradient);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
}

.lang-selector-box {
    display: flex;
    align-items: center;
    gap: 8px;
    background: rgba(10, 6, 22, 0.95);
    border: 1.5px solid var(--gold-primary);
    padding: 6px 14px;
    border-radius: 30px;
    box-shadow: 0 0 12px var(--gold-glow);
}

.lang-icon {
    color: var(--gold-primary);
    font-size: 1rem;
}

.lang-dropdown {
    background: transparent;
    border: none;
    color: var(--gold-light);
    font-family: var(--font-heading);
    font-size: 0.9rem;
    font-weight: 700;
    outline: none;
    cursor: pointer;
}

.lang-dropdown option {
    background: #130B27;
    color: #F8FAFC;
    padding: 10px;
}

/* Classy Header */
.app-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 16px 24px;
    background: rgba(19, 11, 39, 0.8);
    backdrop-filter: blur(24px);
    border: 1px solid var(--card-border);
    border-radius: var(--radius-lg);
    margin-bottom: 20px;
    box-shadow: 0 12px 40px rgba(0, 0, 0, 0.5);
}

.header-logo {
    display: flex;
    align-items: center;
    gap: 16px;
}

.logo-icon {
    font-size: 2.2rem;
    color: var(--gold-primary);
    filter: drop-shadow(0 0 12px var(--gold-glow));
    animation: royalPulse 3s ease-in-out infinite alternate;
}

@keyframes royalPulse {
    0% { transform: scale(1); filter: drop-shadow(0 0 10px var(--gold-glow)); }
    100% { transform: scale(1.05); filter: drop-shadow(0 0 22px var(--gold-primary)); }
}

.logo-text h1 {
    font-family: var(--font-serif);
    font-size: 1.75rem;
    font-weight: 700;
    letter-spacing: 0.5px;
    background: var(--gold-gradient);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
}

.sub-logo {
    font-size: 0.82rem;
    color: var(--text-muted);
    letter-spacing: 0.8px;
    font-weight: 400;
}

/* Desktop Navigation */
.nav-tabs {
    display: flex;
    gap: 6px;
    background: rgba(10, 6, 22, 0.7);
    padding: 5px;
    border-radius: 50px;
    border: 1px solid rgba(223, 172, 108, 0.15);
}

.nav-btn {
    background: transparent;
    border: none;
    color: var(--text-muted);
    padding: 10px 20px;
    border-radius: 40px;
    font-family: var(--font-heading);
    font-size: 0.92rem;
    font-weight: 500;
    cursor: pointer;
    transition: var(--transition-smooth);
    display: flex;
    align-items: center;
    gap: 8px;
}

.nav-btn:hover {
    color: var(--soft-white);
    background: rgba(223, 172, 108, 0.1);
}

.nav-btn.active {
    background: var(--gold-gradient);
    color: #0A0616;
    font-weight: 700;
    box-shadow: 0 4px 18px var(--gold-glow);
}

/* Mobile Bottom Navigation Bar */
.mobile-bottom-nav {
    display: none;
    position: fixed;
    bottom: 0;
    left: 0;
    width: 100%;
    height: 68px;
    background: rgba(15, 9, 31, 0.96);
    backdrop-filter: blur(24px);
    border-top: 1px solid var(--card-border);
    justify-content: space-around;
    align-items: center;
    z-index: 999;
}

.mobile-nav-btn {
    background: transparent;
    border: none;
    color: var(--text-muted);
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 4px;
    font-size: 0.72rem;
    cursor: pointer;
    flex: 1;
    transition: var(--transition-smooth);
}

.mobile-nav-btn i { font-size: 1.25rem; }

.mobile-nav-btn.active {
    color: var(--gold-primary);
}

.mobile-nav-btn.active i {
    filter: drop-shadow(0 0 10px var(--gold-glow));
    transform: translateY(-2px);
}

@media (max-width: 840px) {
    .desktop-nav { display: none; }
    .mobile-bottom-nav { display: flex; }
    .app-header { display: none; } /* Hide large header on mobile, use top-bar */
}

/* Main Cards System */
.main-content { flex: 1; display: flex; flex-direction: column; }

.tab-section { display: none; animation: fadeIn 0.4s ease-out forwards; }
.tab-section.active { display: block; }

@keyframes fadeIn {
    from { opacity: 0; transform: translateY(12px); }
    to { opacity: 1; transform: translateY(0); }
}

.section-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 24px;
}

@media (max-width: 900px) {
    .section-grid { grid-template-columns: 1fr; }
}

.glass-card {
    background: var(--card-bg);
    backdrop-filter: blur(24px);
    border: 1px solid var(--card-border);
    border-radius: var(--radius-lg);
    padding: 24px;
    box-shadow: 0 20px 50px rgba(0, 0, 0, 0.6);
    display: flex;
    flex-direction: column;
    gap: 18px;
    position: relative;
    overflow: hidden;
}

.card-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    border-bottom: 1px solid rgba(223, 172, 108, 0.12);
    padding-bottom: 14px;
}

.card-header h2 {
    font-family: var(--font-serif);
    font-size: 1.3rem;
    font-weight: 700;
    color: var(--soft-white);
    display: flex;
    align-items: center;
    gap: 10px;
}

.card-header h2 i { color: var(--gold-primary); }

.card-header p {
    font-size: 0.85rem;
    color: var(--text-muted);
}

.badge-shastra {
    background: rgba(223, 172, 108, 0.12);
    color: var(--gold-primary);
    border: 1px solid var(--gold-primary);
    padding: 4px 12px;
    border-radius: 20px;
    font-size: 0.78rem;
    font-weight: 600;
}

/* Scanner Viewport */
.scanner-viewport {
    position: relative;
    width: 100%;
    height: 350px;
    background: #05030B;
    border-radius: var(--radius-md);
    border: 1px solid var(--card-border);
    overflow: hidden;
    display: flex;
    justify-content: center;
    align-items: center;
}

#webcamFeed, #previewImage { width: 100%; height: 100%; object-fit: cover; }
#palmOverlayCanvas { position: absolute; top: 0; left: 0; width: 100%; height: 100%; pointer-events: none; }

.scanner-placeholder {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 14px;
    color: var(--text-muted);
    text-align: center;
    padding: 20px;
}

.placeholder-icon {
    font-size: 3.8rem;
    color: var(--gold-primary);
    opacity: 0.7;
}

.scan-laser {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 3px;
    background: linear-gradient(90deg, transparent, var(--gold-primary), transparent);
    box-shadow: 0 0 15px var(--gold-primary);
    animation: laserScan 2.2s linear infinite alternate;
}

@keyframes laserScan {
    0% { top: 0%; }
    100% { top: 98%; }
}

.scanner-actions { display: flex; gap: 12px; flex-wrap: wrap; }

.btn {
    padding: 12px 24px;
    border-radius: 40px;
    border: none;
    font-family: var(--font-heading);
    font-size: 0.92rem;
    font-weight: 600;
    cursor: pointer;
    transition: var(--transition-smooth);
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
}

.btn-primary {
    background: linear-gradient(135deg, var(--velvet-violet), #4C1D95);
    color: #FFF;
    box-shadow: 0 4px 18px var(--velvet-glow);
}

.btn-secondary {
    background: rgba(255, 255, 255, 0.08);
    color: var(--soft-white);
    border: 1px solid rgba(223, 172, 108, 0.2);
}

.btn-accent {
    background: linear-gradient(135deg, #059669, #047857);
    color: #FFF;
}

.btn-gold {
    background: var(--gold-gradient);
    color: #0A0616;
    font-weight: 700;
    box-shadow: 0 4px 18px var(--gold-glow);
}

.btn-sm { padding: 6px 14px; font-size: 0.82rem; }
.btn-danger-sm {
    background: rgba(248, 113, 113, 0.15);
    color: var(--error-red);
    border: 1px solid var(--error-red);
    padding: 6px 14px;
    font-size: 0.8rem;
    border-radius: 20px;
}

.full-width { width: 100%; }
.hidden-input { display: none; }
.hidden { display: none !important; }

.loading-state {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 16px;
    padding: 40px 0;
    text-align: center;
}

.spinner {
    width: 46px;
    height: 46px;
    border: 4px solid rgba(223, 172, 108, 0.2);
    border-top: 4px solid var(--gold-primary);
    border-radius: 50%;
    animation: spin 1s linear infinite;
}

@keyframes spin { to { transform: rotate(360deg); } }

.scores-row {
    display: flex;
    gap: 18px;
    align-items: center;
    background: rgba(10, 6, 22, 0.6);
    padding: 16px;
    border-radius: var(--radius-md);
    border: 1px solid rgba(223, 172, 108, 0.1);
}

.gauge-container {
    position: relative;
    width: 94px;
    height: 94px;
    flex-shrink: 0;
}

.gauge-svg { width: 100%; height: 100%; transform: rotate(-90deg); }
.gauge-bg { fill: none; stroke: rgba(255, 255, 255, 0.08); stroke-width: 8; }
.gauge-fill {
    fill: none;
    stroke: var(--gold-primary);
    stroke-width: 8;
    stroke-linecap: round;
    stroke-dasharray: 251;
    stroke-dashoffset: 30;
    transition: stroke-dashoffset 1.5s ease-out;
}

.gauge-text {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    text-align: center;
    display: flex;
    flex-direction: column;
}

.gauge-text span { font-size: 1.15rem; font-weight: 700; color: var(--gold-primary); }
.gauge-text small { font-size: 0.62rem; color: var(--text-muted); }

.line-scores-list { flex: 1; display: flex; flex-direction: column; gap: 7px; }
.score-item { display: grid; grid-template-columns: 95px 1fr 38px; align-items: center; font-size: 0.8rem; gap: 8px; }
.progress-bar { height: 5px; background: rgba(255, 255, 255, 0.08); border-radius: 4px; overflow: hidden; }
.progress-fill { height: 100%; background: var(--gold-gradient); }

.reading-text-box {
    background: rgba(10, 6, 22, 0.65);
    border: 1px solid rgba(223, 172, 108, 0.12);
    border-radius: var(--radius-md);
    padding: 20px;
    font-size: 0.92rem;
    line-height: 1.7;
    max-height: 280px;
    overflow-y: auto;
}

.reading-text-box h3 {
    font-family: var(--font-serif);
    color: var(--gold-primary);
    margin: 12px 0 6px 0;
    font-size: 1.05rem;
}

.reading-text-box ul { margin-left: 18px; margin-bottom: 10px; }
.result-actions { display: flex; gap: 12px; }

.form-grid { display: flex; flex-direction: column; gap: 14px; }
.form-group { display: flex; flex-direction: column; gap: 6px; }
.form-group label { font-size: 0.85rem; color: var(--text-muted); }
.form-group input {
    background: rgba(10, 6, 22, 0.7);
    border: 1px solid rgba(223, 172, 108, 0.2);
    padding: 12px 16px;
    border-radius: var(--radius-sm);
    color: var(--soft-white);
    font-size: 0.92rem;
    outline: none;
    transition: var(--transition-smooth);
}

.kundli-chart-wrapper { display: flex; flex-direction: column; align-items: center; gap: 18px; }

.diamond-kundli {
    width: 250px;
    height: 250px;
    background: rgba(10, 6, 22, 0.85);
    border-radius: var(--radius-md);
    padding: 8px;
    border: 1px solid var(--gold-primary);
    box-shadow: inset 0 0 20px rgba(0, 0, 0, 0.8);
}

.kundli-svg { width: 100%; height: 100%; }

.kundli-analysis-text {
    background: rgba(10, 6, 22, 0.65);
    padding: 16px;
    border-radius: var(--radius-md);
    border: 1px solid rgba(223, 172, 108, 0.12);
    width: 100%;
    font-size: 0.9rem;
    line-height: 1.6;
}

.tarot-wrapper { align-items: center; }
.tarot-deck-container { display: flex; justify-content: center; gap: 16px; margin: 20px 0; flex-wrap: wrap; }
.tarot-card-item { width: 130px; height: 205px; perspective: 1000px; cursor: pointer; }
.tarot-card-inner {
    position: relative;
    width: 100%;
    height: 100%;
    transition: transform 0.8s cubic-bezier(0.175, 0.885, 0.32, 1.275);
    transform-style: preserve-3d;
    border-radius: var(--radius-md);
}

.tarot-card-item.flipped .tarot-card-inner { transform: rotateY(180deg); }

.tarot-card-front, .tarot-card-back {
    position: absolute;
    width: 100%;
    height: 100%;
    backface-visibility: hidden;
    border-radius: var(--radius-md);
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 12px;
    text-align: center;
}

.tarot-card-back {
    background: linear-gradient(135deg, #1D103A, #0D071B);
    border: 2px solid var(--gold-primary);
    color: var(--gold-primary);
    box-shadow: 0 8px 25px rgba(0, 0, 0, 0.6);
}

.tarot-card-front {
    background: linear-gradient(135deg, #180D33, #2B155B);
    border: 2px solid var(--gold-primary);
    color: var(--soft-white);
    transform: rotateY(180deg);
}

.num-badges-row { display: flex; gap: 16px; justify-content: center; }

.num-badge-card {
    background: rgba(10, 6, 22, 0.7);
    border: 1px solid rgba(223, 172, 108, 0.15);
    padding: 18px;
    border-radius: var(--radius-md);
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 8px;
    flex: 1;
}

.num-circle {
    width: 65px;
    height: 65px;
    border-radius: 50%;
    background: linear-gradient(135deg, var(--velvet-violet), #4C1D95);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.8rem;
    font-weight: 700;
    color: #FFF;
}

.num-circle.gold {
    background: var(--gold-gradient);
    color: #0A0616;
}

.history-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(270px, 1fr));
    gap: 16px;
}

.history-item-card {
    background: rgba(10, 6, 22, 0.7);
    border: 1px solid rgba(223, 172, 108, 0.15);
    border-radius: var(--radius-md);
    padding: 16px;
    display: flex;
    flex-direction: column;
    gap: 10px;
}

.app-footer {
    text-align: center;
    padding: 20px 0;
    margin-top: 24px;
    color: var(--text-muted);
    font-size: 0.82rem;
}

/* ==========================================================================
   AI Palmistry Pro - Royal Midnight & Antique Gold Classy Design System
   ========================================================================== */

@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,600;0,700;1,400&family=Outfit:wght@300;400;500;600;700&family=Noto+Serif+Devanagari:wght@400;500;600;700&display=swap');

:root {
    --bg-dark: #0A0616;
    --royal-indigo: #130B27;
    --card-bg: rgba(23, 14, 46, 0.75);
    --card-border: rgba(223, 172, 108, 0.22);
    --card-border-glow: rgba(223, 172, 108, 0.45);

    /* Antique Gold Palette */
    --gold-primary: #DFAC6C;
    --gold-light: #F7E2BD;
    --gold-dark: #A67537;
    --gold-gradient: linear-gradient(135deg, #F7E2BD 0%, #DFAC6C 50%, #B88544 100%);
    --gold-glow: rgba(223, 172, 108, 0.25);

    /* Deep Velvet Violet Accents */
    --velvet-violet: #6D28D9;
    --velvet-glow: rgba(109, 40, 217, 0.35);

    --soft-white: #F8FAFC;
    --text-muted: #94A3B8;
    --error-red: #F87171;

    --radius-lg: 20px;
    --radius-md: 14px;
    --radius-sm: 8px;

    --font-serif: 'Playfair Display', serif;
    --font-heading: 'Outfit', sans-serif;
    --font-body: 'Noto Serif Devanagari', 'Outfit', serif;

    --transition-smooth: all 0.35s cubic-bezier(0.16, 1, 0.3, 1);
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
    font-family: var(--font-body);
    -webkit-tap-highlight-color: transparent;
}

body {
    background: radial-gradient(circle at 50% 0%, #1D103A 0%, #0A0616 70%);
    color: var(--soft-white);
    min-height: 100vh;
    overflow-x: hidden;
    position: relative;
    padding-bottom: 75px;
}

/* Background Cosmic Canvas */
#starsCanvas {
    position: fixed;
    top: 0;
    left: 0;
    width: 100vw;
    height: 100vh;
    z-index: 0;
    pointer-events: none;
    opacity: 0.85;
}

/* PWA Install Banner */
.pwa-install-banner {
    position: fixed;
    top: 14px;
    left: 50%;
    transform: translateX(-50%);
    width: 92%;
    max-width: 520px;
    background: rgba(19, 11, 39, 0.95);
    backdrop-filter: blur(24px);
    border: 1px solid var(--gold-primary);
    border-radius: var(--radius-md);
    padding: 12px 20px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    z-index: 9999;
    box-shadow: 0 12px 35px rgba(0, 0, 0, 0.7), 0 0 20px var(--gold-glow);
    animation: slideDown 0.5s cubic-bezier(0.16, 1, 0.3, 1);
}

@keyframes slideDown {
    from { transform: translate(-50%, -40px); opacity: 0; }
    to { transform: translate(-50%, 0); opacity: 1; }
}

.pwa-install-info {
    display: flex;
    align-items: center;
    gap: 14px;
}

.pwa-icon {
    font-size: 1.8rem;
    color: var(--gold-primary);
}

.pwa-install-info strong {
    font-family: var(--font-heading);
    font-size: 0.95rem;
    color: var(--soft-white);
}

.pwa-install-info span {
    font-size: 0.78rem;
    color: var(--text-muted);
}

/* App Main Layout Container */
#appContainer {
    position: relative;
    z-index: 1;
    max-width: 1280px;
    margin: 0 auto;
    padding: 20px 16px;
    display: flex;
    flex-direction: column;
    min-height: 100vh;
}

/* Classy Header */
.app-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 16px 24px;
    background: rgba(19, 11, 39, 0.85);
    backdrop-filter: blur(24px);
    border: 1px solid var(--card-border);
    border-radius: var(--radius-lg);
    margin-bottom: 20px;
    box-shadow: 0 12px 40px rgba(0, 0, 0, 0.5);
}

.header-logo {
    display: flex;
    align-items: center;
    gap: 16px;
}

.logo-icon {
    font-size: 2.2rem;
    color: var(--gold-primary);
    filter: drop-shadow(0 0 12px var(--gold-glow));
    animation: royalPulse 3s ease-in-out infinite alternate;
}

@keyframes royalPulse {
    0% { transform: scale(1); filter: drop-shadow(0 0 10px var(--gold-glow)); }
    100% { transform: scale(1.05); filter: drop-shadow(0 0 22px var(--gold-primary)); }
}

.logo-text h1 {
    font-family: var(--font-serif);
    font-size: 1.75rem;
    font-weight: 700;
    letter-spacing: 0.5px;
    background: var(--gold-gradient);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
}

.sub-logo {
    font-size: 0.82rem;
    color: var(--text-muted);
    letter-spacing: 0.8px;
    font-weight: 400;
}

.header-right-group {
    display: flex;
    align-items: center;
    gap: 14px;
}

/* Multi-Language Selector Dropdown Pill */
.lang-selector-box {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    background: rgba(10, 6, 22, 0.95);
    border: 1.5px solid var(--gold-primary);
    padding: 8px 16px;
    border-radius: 40px;
    box-shadow: 0 4px 15px rgba(0, 0, 0, 0.5), 0 0 12px var(--gold-glow);
    transition: var(--transition-smooth);
}

.lang-selector-box:hover {
    border-color: var(--gold-light);
    box-shadow: 0 0 20px var(--gold-primary);
}

.lang-icon {
    color: var(--gold-primary);
    font-size: 1.1rem;
}

.lang-dropdown {
    background: transparent;
    border: none;
    color: var(--gold-light);
    font-family: var(--font-heading);
    font-size: 0.92rem;
    font-weight: 700;
    outline: none;
    cursor: pointer;
}

.lang-dropdown option {
    background: #130B27;
    color: #F8FAFC;
    padding: 10px;
}

/* Desktop Navigation */
.nav-tabs {
    display: flex;
    gap: 6px;
    background: rgba(10, 6, 22, 0.7);
    padding: 5px;
    border-radius: 50px;
    border: 1px solid rgba(223, 172, 108, 0.15);
}

.nav-btn {
    background: transparent;
    border: none;
    color: var(--text-muted);
    padding: 10px 20px;
    border-radius: 40px;
    font-family: var(--font-heading);
    font-size: 0.92rem;
    font-weight: 500;
    cursor: pointer;
    transition: var(--transition-smooth);
    display: flex;
    align-items: center;
    gap: 8px;
}

.nav-btn:hover {
    color: var(--soft-white);
    background: rgba(223, 172, 108, 0.1);
}

.nav-btn.active {
    background: var(--gold-gradient);
    color: #0A0616;
    font-weight: 700;
    box-shadow: 0 4px 18px var(--gold-glow);
}

/* Mobile Bottom Navigation Bar */
.mobile-bottom-nav {
    display: none;
    position: fixed;
    bottom: 0;
    left: 0;
    width: 100%;
    height: 68px;
    background: rgba(15, 9, 31, 0.96);
    backdrop-filter: blur(24px);
    border-top: 1px solid var(--card-border);
    justify-content: space-around;
    align-items: center;
    z-index: 999;
}

.mobile-nav-btn {
    background: transparent;
    border: none;
    color: var(--text-muted);
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 4px;
    font-size: 0.72rem;
    cursor: pointer;
    flex: 1;
    transition: var(--transition-smooth);
}

.mobile-nav-btn i { font-size: 1.25rem; }

.mobile-nav-btn.active {
    color: var(--gold-primary);
}

.mobile-nav-btn.active i {
    filter: drop-shadow(0 0 10px var(--gold-glow));
    transform: translateY(-2px);
}

@media (max-width: 960px) {
    .desktop-nav { display: none; }
    .mobile-bottom-nav { display: flex; }
    .app-header { flex-direction: row; justify-content: space-between; gap: 12px; }
}

@media (max-width: 600px) {
    .app-header { flex-direction: column; text-align: center; gap: 12px; }
    .header-logo { justify-content: center; }
}

