    function extractRealPalmLineScores() {
        const tempCanvas = document.createElement('canvas');
        const tCtx = tempCanvas.getContext('2d');
        const w = 100;
        const h = 100;
        tempCanvas.width = w;
        tempCanvas.height = h;

