                head: Math.min(98, Math.max(70, Math.round(78 + (headLineVal % 18)))),
                life: Math.min(95, Math.max(72, Math.round(80 + (lifeLineVal % 16)))),
                fate: Math.min(92, Math.max(65, Math.round(70 + (fateLineVal % 22))))
            };
