    --gold-primary: #DFAC6C;
    --gold-light: #F7E2BD;
    --gold-dark: #A67537;
    --gold-gradient: linear-gradient(135deg, #F7E2BD 0%, #DFAC6C 50%, #B88544 100%);
    --gold-glow: rgba(223, 172, 108, 0.25);

    /* Deep Velvet Violet Accents */
    --velvet-violet: #6D28D9;
    --velvet-glow: rgba(109, 40, 217, 0.35);

    --soft-white: #F8FAFC;
    --text-muted: #94A3B8;
    --error-red: #F87171;

    --radius-lg: 20px;
    --radius-md: 14px;
    --radius-sm: 8px;

    --font-serif: 'Playfair Display', serif;
    --font-heading: 'Outfit', sans-serif;
    --font-body: 'Noto Serif Devanagari', 'Outfit', serif;

    --transition-smooth: all 0.35s cubic-bezier(0.16, 1, 0.3, 1);
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
    font-family: var(--font-body);
    -webkit-tap-highlight-color: transparent;
}

body {
    background: radial-gradient(circle at 50% 0%, #1D103A 0%, #0A0616 70%);
    color: var(--soft-white);
    min-height: 100vh;
    overflow-x: hidden;
    position: relative;
    padding-bottom: 75px;
}

/* Background Cosmic Canvas */
#starsCanvas {
    position: fixed;
    top: 0;
    left: 0;
    width: 100vw;
    height: 100vh;
    z-index: 0;
    pointer-events: none;
    opacity: 0.85;
}

/* PWA Install Banner */
.pwa-install-banner {
    position: fixed;
    top: 14px;
    left: 50%;
    transform: translateX(-50%);
    width: 92%;
    max-width: 520px;
    background: rgba(19, 11, 39, 0.95);
    backdrop-filter: blur(24px);
    border: 1px solid var(--gold-primary);
    border-radius: var(--radius-md);
    padding: 12px 20px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    z-index: 9999;
    box-shadow: 0 12px 35px rgba(0, 0, 0, 0.7), 0 0 20px var(--gold-glow);
    animation: slideDown 0.5s cubic-bezier(0.16, 1, 0.3, 1);
}

@keyframes slideDown {
    from { transform: translate(-50%, -40px); opacity: 0; }
    to { transform: translate(-50%, 0); opacity: 1; }
}

.pwa-install-info {
    display: flex;
    align-items: center;
    gap: 14px;
}

.pwa-icon {
    font-size: 1.8rem;
    color: var(--gold-primary);
}

.pwa-install-info strong {
    font-family: var(--font-heading);
    font-size: 0.95rem;
    color: var(--soft-white);
}

.pwa-install-info span {
    font-size: 0.78rem;
    color: var(--text-muted);
}

/* App Main Layout Container */
#appContainer {
    position: relative;
    z-index: 1;
    max-width: 1280px;
    margin: 0 auto;
    padding: 20px 16px;
    display: flex;
    flex-direction: column;
    min-height: 100vh;
}

/* Classy Header */
.app-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 16px 24px;
    background: rgba(19, 11, 39, 0.85);
    backdrop-filter: blur(24px);
    border: 1px solid var(--card-border);
    border-radius: var(--radius-lg);
    margin-bottom: 20px;
    box-shadow: 0 12px 40px rgba(0, 0, 0, 0.5);
}

.header-logo {
    display: flex;
    align-items: center;
    gap: 16px;
}

.logo-icon {
    font-size: 2.2rem;
    color: var(--gold-primary);
    filter: drop-shadow(0 0 12px var(--gold-glow));
    animation: royalPulse 3s ease-in-out infinite alternate;
}

@keyframes royalPulse {
    0% { transform: scale(1); filter: drop-shadow(0 0 10px var(--gold-glow)); }
    100% { transform: scale(1.05); filter: drop-shadow(0 0 22px var(--gold-primary)); }
}

.logo-text h1 {
    font-family: var(--font-serif);
    font-size: 1.75rem;
    font-weight: 700;
    letter-spacing: 0.5px;
    background: var(--gold-gradient);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
}

.sub-logo {
    font-size: 0.82rem;
    color: var(--text-muted);
    letter-spacing: 0.8px;
    font-weight: 400;
}

.header-right-group {
    display: flex;
    align-items: center;
    gap: 14px;
}

/* Multi-Language Selector Dropdown Pill */
.lang-selector-box {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    background: rgba(10, 6, 22, 0.95);
    border: 1.5px solid var(--gold-primary);
    padding: 8px 16px;
    border-radius: 40px;
    box-shadow: 0 4px 15px rgba(0, 0, 0, 0.5), 0 0 12px var(--gold-glow);
    transition: var(--transition-smooth);
}

.lang-selector-box:hover {
    border-color: var(--gold-light);
    box-shadow: 0 0 20px var(--gold-primary);
}

.lang-icon {
    color: var(--gold-primary);
    font-size: 1.1rem;
}

.lang-dropdown {
    background: transparent;
    border: none;
    color: var(--gold-light);
    font-family: var(--font-heading);
    font-size: 0.92rem;
    font-weight: 700;
    outline: none;
    cursor: pointer;
}

.lang-dropdown option {
    background: #130B27;
    color: #F8FAFC;
    padding: 10px;
}

/* Desktop Navigation */
.nav-tabs {
    display: flex;
    gap: 6px;
    background: rgba(10, 6, 22, 0.7);
    padding: 5px;
    border-radius: 50px;
    border: 1px solid rgba(223, 172, 108, 0.15);
}

.nav-btn {
    background: transparent;
    border: none;
    color: var(--text-muted);
    padding: 10px 20px;
    border-radius: 40px;
    font-family: var(--font-heading);
    font-size: 0.92rem;
    font-weight: 500;
    cursor: pointer;
    transition: var(--transition-smooth);
    display: flex;
    align-items: center;
    gap: 8px;
}

.nav-btn:hover {
    color: var(--soft-white);
    background: rgba(223, 172, 108, 0.1);
}

.nav-btn.active {
    background: var(--gold-gradient);
    color: #0A0616;
    font-weight: 700;
    box-shadow: 0 4px 18px var(--gold-glow);
}

/* Mobile Bottom Navigation Bar */
.mobile-bottom-nav {
    display: none;
    position: fixed;
    bottom: 0;
    left: 0;
    width: 100%;
    height: 68px;
    background: rgba(15, 9, 31, 0.96);
    backdrop-filter: blur(24px);
    border-top: 1px solid var(--card-border);
    justify-content: space-around;
    align-items: center;
    z-index: 999;
}

.mobile-nav-btn {
    background: transparent;
    border: none;
    color: var(--text-muted);
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 4px;
    font-size: 0.72rem;
    cursor: pointer;
    flex: 1;
    transition: var(--transition-smooth);
}

.mobile-nav-btn i { font-size: 1.25rem; }

.mobile-nav-btn.active {
    color: var(--gold-primary);
}

.mobile-nav-btn.active i {
    filter: drop-shadow(0 0 10px var(--gold-glow));
    transform: translateY(-2px);
}

@media (max-width: 960px) {
    .desktop-nav { display: none; }
    .mobile-bottom-nav { display: flex; }
    .app-header { flex-direction: row; justify-content: space-between; gap: 12px; }
}

@media (max-width: 600px) {
    .app-header { flex-direction: column; text-align: center; gap: 12px; }
    .header-logo { justify-content: center; }
}

/* 4-Layer Major Verification Pipeline Bar */
.pipeline-bar {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 12px;
    margin-bottom: 20px;
}

@media (max-width: 800px) {
    .pipeline-bar {
        grid-template-columns: repeat(2, 1fr);
    }
}

.pipeline-step {
    background: rgba(19, 11, 39, 0.85);
    border: 1px solid var(--card-border);
    border-radius: var(--radius-md);
    padding: 10px 14px;
    display: flex;
    align-items: center;
    gap: 10px;
    font-size: 0.82rem;
    color: var(--text-muted);
    transition: var(--transition-smooth);
}

.pipeline-step i {
    font-size: 1.1rem;
    color: var(--gold-primary);
}

.pipeline-step.active {
    border-color: var(--gold-primary);
    color: var(--gold-light);
    box-shadow: 0 4px 15px var(--gold-glow);
}

/* 3D Palm & Mount Reference Guide */
.hand-guide-card {
    display: flex;
    flex-direction: column;
    gap: 16px;
}

.guide-subtitle {
    font-size: 0.88rem;
    color: var(--text-muted);
}

.guide-content-row {
    display: grid;
    grid-template-columns: 320px 1fr;
    gap: 24px;
    align-items: center;
}

@media (max-width: 768px) {
    .guide-content-row {
        grid-template-columns: 1fr;
    }
}

.hand-svg-wrapper {
    background: rgba(10, 6, 22, 0.7);
    border: 1px solid var(--card-border);
    border-radius: var(--radius-md);
    padding: 16px;
    display: flex;
    justify-content: center;
    align-items: center;
}

.interactive-hand-svg {
    width: 100%;
    max-width: 280px;
    height: auto;
}

.mount-circle {
    cursor: pointer;
    transition: var(--transition-smooth);
}

.mount-circle:hover {
    fill: rgba(223, 172, 108, 0.7);
    stroke: var(--gold-light);
    filter: drop-shadow(0 0 12px var(--gold-primary));
}

.guide-line-path {
    cursor: pointer;
    transition: var(--transition-smooth);
}

.guide-line-path:hover {
    stroke-width: 5;
    filter: drop-shadow(0 0 10px #FFF);
}

.guide-details-box {
    background: rgba(10, 6, 22, 0.8);
    border: 1.5px solid var(--gold-primary);
    border-radius: var(--radius-md);
    padding: 20px;
    display: flex;
    flex-direction: column;
    gap: 12px;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5);
}

.guide-info-header {
    display: flex;
    align-items: center;
    gap: 10px;
    font-size: 1.1rem;
    color: var(--gold-primary);
}

.guide-info-desc {
    font-size: 0.92rem;
    line-height: 1.7;
    color: var(--soft-white);
}

/* Interactive Scripture Chatbot */
.shastra-chat-container {
    background: rgba(10, 6, 22, 0.7);
    border: 1px solid var(--gold-primary);
    border-radius: var(--radius-md);
    padding: 16px;
    display: flex;
    flex-direction: column;
    gap: 12px;
    margin-top: 10px;
}

.chat-header {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 0.92rem;
    color: var(--gold-light);
    border-bottom: 1px solid rgba(223, 172, 108, 0.15);
    padding-bottom: 8px;
}

.chat-messages-box {
    display: flex;
    flex-direction: column;
    gap: 10px;
    max-height: 220px;
    overflow-y: auto;
    padding-right: 6px;
}

.chat-msg {
    padding: 10px 14px;
    border-radius: var(--radius-sm);
    font-size: 0.88rem;
    line-height: 1.5;
    max-width: 88%;
}

.bot-msg {
    background: rgba(109, 40, 217, 0.25);
    border: 1px solid rgba(109, 40, 217, 0.4);
    color: var(--soft-white);
    align-self: flex-start;
}

.user-msg {
    background: rgba(223, 172, 108, 0.2);
    border: 1px solid var(--gold-primary);
    color: var(--gold-light);
    align-self: flex-end;
}

.chat-input-row {
    display: flex;
    gap: 8px;
}

.chat-input-row input {
    flex: 1;
    background: rgba(19, 11, 39, 0.95);
    border: 1px solid rgba(223, 172, 108, 0.3);
    padding: 10px 14px;
    border-radius: var(--radius-sm);
    color: var(--soft-white);
    font-size: 0.88rem;
    outline: none;
}

/* Step-2 Verification Box */
.verification-box {
    display: flex;
    flex-direction: column;
    gap: 16px;
    animation: fadeIn 0.4s ease-out;
}

.verify-subtitle {
    font-size: 0.88rem;
    color: var(--text-muted);
    line-height: 1.5;
}

.verify-form-grid {
    display: flex;
    flex-direction: column;
    gap: 14px;
    background: rgba(10, 6, 22, 0.6);
    padding: 16px;
    border-radius: var(--radius-md);
    border: 1px solid rgba(223, 172, 108, 0.15);
}

.verify-group {
    display: flex;
    flex-direction: column;
    gap: 6px;
}

.verify-group label {
    font-size: 0.88rem;
    color: var(--soft-white);
    display: flex;
    align-items: center;
    gap: 6px;
}

.verify-select {
    background: rgba(19, 11, 39, 0.95);
    border: 1px solid var(--gold-primary);
    padding: 10px 14px;
    border-radius: var(--radius-sm);
    color: var(--gold-light);
    font-family: var(--font-heading);
    font-size: 0.9rem;
    font-weight: 600;
    outline: none;
}

.verify-select option {
    background: #130B27;
    color: #F8FAFC;
}

/* Main Cards System */
.main-content { flex: 1; display: flex; flex-direction: column; }

.tab-section { display: none; animation: fadeIn 0.4s ease-out forwards; }
.tab-section.active { display: block; }

@keyframes fadeIn {
    from { opacity: 0; transform: translateY(12px); }
    to { opacity: 1; transform: translateY(0); }
}

.section-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 24px;
}

@media (max-width: 900px) {
    .section-grid { grid-template-columns: 1fr; }
}

.glass-card {
    background: var(--card-bg);
    backdrop-filter: blur(24px);
    border: 1px solid var(--card-border);
    border-radius: var(--radius-lg);
    padding: 24px;
    box-shadow: 0 20px 50px rgba(0, 0, 0, 0.6);
    display: flex;
    flex-direction: column;
    gap: 18px;
    position: relative;
    overflow: hidden;
}

.card-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    border-bottom: 1px solid rgba(223, 172, 108, 0.12);
    padding-bottom: 14px;
}

.card-header h2 {
    font-family: var(--font-serif);
    font-size: 1.3rem;
    font-weight: 700;
    color: var(--soft-white);
    display: flex;
    align-items: center;
    gap: 10px;
}

.card-header h2 i { color: var(--gold-primary); }

.card-header p {
    font-size: 0.85rem;
    color: var(--text-muted);
}

.badge-shastra {
    background: rgba(223, 172, 108, 0.12);
    color: var(--gold-primary);
    border: 1px solid var(--gold-primary);
    padding: 4px 12px;
    border-radius: 20px;
    font-size: 0.78rem;
    font-weight: 600;
}

/* Scanner Viewport */
.scanner-viewport {
    position: relative;
    width: 100%;
    height: 350px;
    background: #05030B;
    border-radius: var(--radius-md);
    border: 1px solid var(--card-border);
    overflow: hidden;
    display: flex;
    justify-content: center;
    align-items: center;
}

#webcamFeed, #previewImage { width: 100%; height: 100%; object-fit: cover; }
#palmOverlayCanvas { position: absolute; top: 0; left: 0; width: 100%; height: 100%; pointer-events: none; }

.scanner-placeholder {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 14px;
    color: var(--text-muted);
    text-align: center;
    padding: 20px;
}

.placeholder-icon {
    font-size: 3.8rem;
    color: var(--gold-primary);
    opacity: 0.7;
}

.scan-laser {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 3px;
    background: linear-gradient(90deg, transparent, var(--gold-primary), transparent);
    box-shadow: 0 0 15px var(--gold-primary);
    animation: laserScan 2.2s linear infinite alternate;
}

@keyframes laserScan {
    0% { top: 0%; }
    100% { top: 98%; }
}

.scanner-actions { display: flex; gap: 12px; flex-wrap: wrap; }

.btn {
    padding: 12px 24px;
    border-radius: 40px;
    border: none;
    font-family: var(--font-heading);
    font-size: 0.92rem;
    font-weight: 600;
    cursor: pointer;
    transition: var(--transition-smooth);
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
}

.btn-primary {
    background: linear-gradient(135deg, var(--velvet-violet), #4C1D95);
    color: #FFF;
    box-shadow: 0 4px 18px var(--velvet-glow);
}

.btn-secondary {
    background: rgba(255, 255, 255, 0.08);
    color: var(--soft-white);
    border: 1px solid rgba(223, 172, 108, 0.2);
}

.btn-accent {
    background: linear-gradient(135deg, #059669, #047857);
    color: #FFF;
}

.btn-gold {
    background: var(--gold-gradient);
    color: #0A0616;
    font-weight: 700;
    box-shadow: 0 4px 18px var(--gold-glow);
}

.btn-sm { padding: 6px 14px; font-size: 0.82rem; }
.btn-danger-sm {
    background: rgba(248, 113, 113, 0.15);
    color: var(--error-red);
    border: 1px solid var(--error-red);
    padding: 6px 14px;
    font-size: 0.8rem;
    border-radius: 20px;
}

.full-width { width: 100%; }
.hidden-input { display: none; }
.hidden { display: none !important; }

.loading-state {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 16px;
    padding: 40px 0;
    text-align: center;
}

.spinner {
    width: 46px;
    height: 46px;
    border: 4px solid rgba(223, 172, 108, 0.2);
    border-top: 4px solid var(--gold-primary);
    border-radius: 50%;
    animation: spin 1s linear infinite;
}

@keyframes spin { to { transform: rotate(360deg); } }

.scores-row {
    display: flex;
    gap: 18px;
    align-items: center;
    background: rgba(10, 6, 22, 0.6);
    padding: 16px;
    border-radius: var(--radius-md);
    border: 1px solid rgba(223, 172, 108, 0.1);
}

.gauge-container {
    position: relative;
    width: 94px;
    height: 94px;
    flex-shrink: 0;
}

.gauge-svg { width: 100%; height: 100%; transform: rotate(-90deg); }
.gauge-bg { fill: none; stroke: rgba(255, 255, 255, 0.08); stroke-width: 8; }
.gauge-fill {
    fill: none;
    stroke: var(--gold-primary);
    stroke-width: 8;
    stroke-linecap: round;
    stroke-dasharray: 251;
    stroke-dashoffset: 30;
    transition: stroke-dashoffset 1.5s ease-out;
}

.gauge-text {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    text-align: center;
    display: flex;
    flex-direction: column;
}

.gauge-text span { font-size: 1.15rem; font-weight: 700; color: var(--gold-primary); }
.gauge-text small { font-size: 0.62rem; color: var(--text-muted); }

.line-scores-list { flex: 1; display: flex; flex-direction: column; gap: 7px; }
.score-item { display: grid; grid-template-columns: 95px 1fr 38px; align-items: center; font-size: 0.8rem; gap: 8px; }
.progress-bar { height: 5px; background: rgba(255, 255, 255, 0.08); border-radius: 4px; overflow: hidden; }
.progress-fill { height: 100%; background: var(--gold-gradient); }

.reading-text-box {
    background: rgba(10, 6, 22, 0.65);
    border: 1px solid rgba(223, 172, 108, 0.12);
    border-radius: var(--radius-md);
    padding: 20px;
    font-size: 0.92rem;
    line-height: 1.7;
    max-height: 320px;
    overflow-y: auto;
}

.reading-text-box h3 {
    font-family: var(--font-serif);
    color: var(--gold-primary);
    margin: 14px 0 8px 0;
    font-size: 1.05rem;
    border-bottom: 1px solid rgba(223, 172, 108, 0.15);
    padding-bottom: 4px;
}

.reading-text-box ul { margin-left: 18px; margin-bottom: 12px; }
.result-actions { display: flex; gap: 12px; }

.form-grid { display: flex; flex-direction: column; gap: 14px; }
.form-group { display: flex; flex-direction: column; gap: 6px; }
.form-group label { font-size: 0.85rem; color: var(--text-muted); }
.form-group input {
    background: rgba(10, 6, 22, 0.7);
    border: 1px solid rgba(223, 172, 108, 0.2);
    padding: 12px 16px;
    border-radius: var(--radius-sm);
    color: var(--soft-white);
    font-size: 0.92rem;
    outline: none;
    transition: var(--transition-smooth);
}

.kundli-chart-wrapper { display: flex; flex-direction: column; align-items: center; gap: 18px; }

.diamond-kundli {
    width: 250px;
    height: 250px;
    background: rgba(10, 6, 22, 0.85);
    border-radius: var(--radius-md);
    padding: 8px;
    border: 1px solid var(--gold-primary);
    box-shadow: inset 0 0 20px rgba(0, 0, 0, 0.8);
}

.kundli-svg { width: 100%; height: 100%; }

.kundli-analysis-text {
    background: rgba(10, 6, 22, 0.65);
    padding: 16px;
    border-radius: var(--radius-md);
    border: 1px solid rgba(223, 172, 108, 0.12);
    width: 100%;
    font-size: 0.9rem;
    line-height: 1.6;
}

.tarot-wrapper { align-items: center; }
.tarot-deck-container { display: flex; justify-content: center; gap: 16px; margin: 20px 0; flex-wrap: wrap; }
.tarot-card-item { width: 130px; height: 205px; perspective: 1000px; cursor: pointer; }
.tarot-card-inner {
    position: relative;
    width: 100%;
    height: 100%;
    transition: transform 0.8s cubic-bezier(0.175, 0.885, 0.32, 1.275);
    transform-style: preserve-3d;
    border-radius: var(--radius-md);
}

.tarot-card-item.flipped .tarot-card-inner { transform: rotateY(180deg); }

.tarot-card-front, .tarot-card-back {
    position: absolute;
    width: 100%;
    height: 100%;
    backface-visibility: hidden;
    border-radius: var(--radius-md);
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 12px;
    text-align: center;
}

.tarot-card-back {
    background: linear-gradient(135deg, #1D103A, #0D071B);
    border: 2px solid var(--gold-primary);
