/* ==========================================================================
   AI Palmistry Pro - Royal Midnight & Antique Gold Classy Design System
   ========================================================================== */

@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,600;0,700;1,400&family=Outfit:wght@300;400;500;600;700&family=Noto+Serif+Devanagari:wght@400;500;600;700&display=swap');

:root {
    --bg-dark: #0A0616;
    --royal-indigo: #130B27;
    --card-bg: rgba(23, 14, 46, 0.75);
    --card-border: rgba(223, 172, 108, 0.22);
    --card-border-glow: rgba(223, 172, 108, 0.45);

    /* Antique Gold Palette */
    --gold-primary: #DFAC6C;
    --gold-light: #F7E2BD;
    --gold-dark: #A67537;
    --gold-gradient: linear-gradient(135deg, #F7E2BD 0%, #DFAC6C 50%, #B88544 100%);
    --gold-glow: rgba(223, 172, 108, 0.25);

    /* Deep Velvet Violet Accents */
    --velvet-violet: #6D28D9;
    --velvet-glow: rgba(109, 40, 217, 0.35);

    --soft-white: #F8FAFC;
    --text-muted: #94A3B8;
    --error-red: #F87171;

    --radius-lg: 20px;
    --radius-md: 14px;
    --radius-sm: 8px;

    --font-serif: 'Playfair Display', serif;
    --font-heading: 'Outfit', sans-serif;
    --font-body: 'Noto Serif Devanagari', 'Outfit', serif;

    --transition-smooth: all 0.35s cubic-bezier(0.16, 1, 0.3, 1);
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
    font-family: var(--font-body);
    -webkit-tap-highlight-color: transparent;
}

body {
    background: radial-gradient(circle at 50% 0%, #1D103A 0%, #0A0616 70%);
    color: var(--soft-white);
    min-height: 100vh;
    overflow-x: hidden;
    position: relative;
    padding-bottom: 75px;
}

/* Background Cosmic Canvas */
#starsCanvas {
    position: fixed;
    top: 0;
    left: 0;
    width: 100vw;
    height: 100vh;
    z-index: 0;
    pointer-events: none;
    opacity: 0.85;
}

/* PWA Install Banner */
.pwa-install-banner {
    position: fixed;
    top: 14px;
    left: 50%;
    transform: translateX(-50%);
    width: 92%;
    max-width: 520px;
    background: rgba(19, 11, 39, 0.95);
    backdrop-filter: blur(24px);
    border: 1px solid var(--gold-primary);
    border-radius: var(--radius-md);
    padding: 12px 20px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    z-index: 9999;
    box-shadow: 0 12px 35px rgba(0, 0, 0, 0.7), 0 0 20px var(--gold-glow);
    animation: slideDown 0.5s cubic-bezier(0.16, 1, 0.3, 1);
}

@keyframes slideDown {
    from { transform: translate(-50%, -40px); opacity: 0; }
    to { transform: translate(-50%, 0); opacity: 1; }
}

.pwa-install-info {
    display: flex;
    align-items: center;
    gap: 14px;
}

.pwa-icon {
    font-size: 1.8rem;
    color: var(--gold-primary);
}

.pwa-install-info strong {
    font-family: var(--font-heading);
    font-size: 0.95rem;
    color: var(--soft-white);
}

.pwa-install-info span {
    font-size: 0.78rem;
    color: var(--text-muted);
}

/* App Main Layout Container */
#appContainer {
    position: relative;
    z-index: 1;
    max-width: 1280px;
    margin: 0 auto;
    padding: 20px 16px;
    display: flex;
    flex-direction: column;
    min-height: 100vh;
}

/* Classy Header */
.app-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 16px 24px;
    background: rgba(19, 11, 39, 0.85);
    backdrop-filter: blur(24px);
    border: 1px solid var(--card-border);
    border-radius: var(--radius-lg);
    margin-bottom: 20px;
    box-shadow: 0 12px 40px rgba(0, 0, 0, 0.5);
}

.header-logo {
    display: flex;
    align-items: center;
    gap: 16px;
}

.logo-icon {
    font-size: 2.2rem;
    color: var(--gold-primary);
    filter: drop-shadow(0 0 12px var(--gold-glow));
    animation: royalPulse 3s ease-in-out infinite alternate;
}

@keyframes royalPulse {
    0% { transform: scale(1); filter: drop-shadow(0 0 10px var(--gold-glow)); }
    100% { transform: scale(1.05); filter: drop-shadow(0 0 22px var(--gold-primary)); }
}

.logo-text h1 {
    font-family: var(--font-serif);
    font-size: 1.75rem;
    font-weight: 700;
    letter-spacing: 0.5px;
    background: var(--gold-gradient);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
}

.sub-logo {
    font-size: 0.82rem;
    color: var(--text-muted);
    letter-spacing: 0.8px;
    font-weight: 400;
}

.header-right-group {
    display: flex;
    align-items: center;
    gap: 14px;
}

/* Multi-Language Selector Dropdown Pill */
.lang-selector-box {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    background: rgba(10, 6, 22, 0.95);
    border: 1.5px solid var(--gold-primary);
    padding: 8px 16px;
    border-radius: 40px;
    box-shadow: 0 4px 15px rgba(0, 0, 0, 0.5), 0 0 12px var(--gold-glow);
    transition: var(--transition-smooth);
}

.lang-selector-box:hover {
    border-color: var(--gold-light);
    box-shadow: 0 0 20px var(--gold-primary);
}

.lang-icon {
    color: var(--gold-primary);
    font-size: 1.1rem;
}

.lang-dropdown {
    background: transparent;
    border: none;
    color: var(--gold-light);
    font-family: var(--font-heading);
    font-size: 0.92rem;
    font-weight: 700;
    outline: none;
    cursor: pointer;
}

.lang-dropdown option {
    background: #130B27;
    color: #F8FAFC;
    padding: 10px;
}

/* Desktop Navigation */
.nav-tabs {
    display: flex;
    gap: 6px;
    background: rgba(10, 6, 22, 0.7);
    padding: 5px;
    border-radius: 50px;
    border: 1px solid rgba(223, 172, 108, 0.15);
}

.nav-btn {
    background: transparent;
    border: none;
    color: var(--text-muted);
    padding: 10px 20px;
    border-radius: 40px;
    font-family: var(--font-heading);
    font-size: 0.92rem;
    font-weight: 500;
    cursor: pointer;
    transition: var(--transition-smooth);
    display: flex;
    align-items: center;
    gap: 8px;
}

.nav-btn:hover {
    color: var(--soft-white);
    background: rgba(223, 172, 108, 0.1);
}

.nav-btn.active {
    background: var(--gold-gradient);
    color: #0A0616;
    font-weight: 700;
    box-shadow: 0 4px 18px var(--gold-glow);
}

/* Mobile Bottom Navigation Bar */
.mobile-bottom-nav {
    display: none;
    position: fixed;
    bottom: 0;
    left: 0;
    width: 100%;
    height: 68px;
    background: rgba(15, 9, 31, 0.96);
    backdrop-filter: blur(24px);
    border-top: 1px solid var(--card-border);
    justify-content: space-around;
    align-items: center;
    z-index: 999;
}

.mobile-nav-btn {
    background: transparent;
    border: none;
    color: var(--text-muted);
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 4px;
    font-size: 0.72rem;
    cursor: pointer;
    flex: 1;
    transition: var(--transition-smooth);
}

.mobile-nav-btn i { font-size: 1.25rem; }

.mobile-nav-btn.active {
    color: var(--gold-primary);
}

.mobile-nav-btn.active i {
    filter: drop-shadow(0 0 10px var(--gold-glow));
    transform: translateY(-2px);
}

@media (max-width: 960px) {
    .desktop-nav { display: none; }
    .mobile-bottom-nav { display: flex; }
    .app-header { flex-direction: row; justify-content: space-between; gap: 12px; }
}

@media (max-width: 600px) {
    .app-header { flex-direction: column; text-align: center; gap: 12px; }
    .header-logo { justify-content: center; }
}

/* 4-Layer Major Verification Pipeline Bar */
.pipeline-bar {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 12px;
    margin-bottom: 20px;
}

@media (max-width: 800px) {
    .pipeline-bar {
        grid-template-columns: repeat(2, 1fr);
    }
}

.pipeline-step {
    background: rgba(19, 11, 39, 0.85);
    border: 1px solid var(--card-border);
    border-radius: var(--radius-md);
    padding: 10px 14px;
    display: flex;
    align-items: center;
    gap: 10px;
    font-size: 0.82rem;
    color: var(--text-muted);
    transition: var(--transition-smooth);
}

.pipeline-step i {
    font-size: 1.1rem;
    color: var(--gold-primary);
}

.pipeline-step.active {
    border-color: var(--gold-primary);
    color: var(--gold-light);
    box-shadow: 0 4px 15px var(--gold-glow);
}

/* Real WebGL Three.js 3D Hand Guide */
.hand-guide-card {
    display: flex;
    flex-direction: column;
    gap: 16px;
}

.guide-subtitle {
    font-size: 0.88rem;
    color: var(--text-muted);
}

.guide-content-row {
    display: grid;
    grid-template-columns: 340px 1fr;
    gap: 24px;
    align-items: center;
}

@media (max-width: 768px) {
    .guide-content-row {
        grid-template-columns: 1fr;
    }
}

.hand-3d-wrapper {
    background: radial-gradient(circle at 50% 50%, #1A0D36 0%, #080412 100%);
    border: 1.5px solid var(--gold-primary);
    border-radius: var(--radius-md);
    padding: 10px;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    position: relative;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.6), inset 0 0 20px rgba(223, 172, 108, 0.15);
}

#hand3DCanvas {
    width: 100%;
