}

.guide-details-box {
    background: rgba(10, 6, 22, 0.8);
    border: 1.5px solid var(--gold-primary);
    border-radius: var(--radius-md);
    padding: 20px;
    display: flex;
    flex-direction: column;
    gap: 12px;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5);
}

.guide-info-header {
    display: flex;
    align-items: center;
    gap: 10px;
    font-size: 1.1rem;
    color: var(--gold-primary);
}

.guide-info-desc {
    font-size: 0.92rem;
    line-height: 1.7;
    color: var(--soft-white);
}

/* Interactive Scripture Chatbot */
.shastra-chat-container {
    background: rgba(10, 6, 22, 0.7);
    border: 1px solid var(--gold-primary);
    border-radius: var(--radius-md);
    padding: 16px;
    display: flex;
    flex-direction: column;
    gap: 12px;
    margin-top: 10px;
}

.chat-header {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 0.92rem;
