}

.bot-msg {
    background: rgba(109, 40, 217, 0.25);
    border: 1px solid rgba(109, 40, 217, 0.4);
    color: var(--soft-white);
    align-self: flex-start;
}

.user-msg {
    background: rgba(223, 172, 108, 0.2);
    border: 1px solid var(--gold-primary);
    color: var(--gold-light);
