    justify-content: center;
    font-size: 1.8rem;
    font-weight: 700;
    color: #FFF;
}

.num-circle.gold {
    background: var(--gold-gradient);
    color: #0A0616;
}

.history-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(270px, 1fr));
    gap: 16px;
}

.history-item-card {
    background: rgba(10, 6, 22, 0.7);
    border: 1px solid rgba(223, 172, 108, 0.15);
    border-radius: var(--radius-md);
    padding: 16px;
    display: flex;
    flex-direction: column;
    gap: 10px;
}

