        let skinDesc = features.skin === 'pink' ? "हथेली का स्निग्ध गुलाबी रंग उत्तम भाग्य, ग्रहों की कृपा एवं उच्च संस्कार दर्शाता है।" : "रक्ताभ हथेली असीम ऊर्जा, पराक्रम एवं नेतृत्व क्षमता का संकेत है।";
