    font-family: var(--font-heading);
    font-size: 0.92rem;
    font-weight: 700;
    outline: none;
    cursor: pointer;
}

.lang-dropdown option {
    background: #130B27;
    color: #F8FAFC;
    padding: 10px;
}

/* Desktop Navigation */
.nav-tabs {
    display: flex;
    gap: 6px;
    background: rgba(10, 6, 22, 0.7);
    padding: 5px;
