    font-weight: 700;
    box-shadow: 0 4px 18px var(--gold-glow);
}

/* Mobile Bottom Navigation Bar */
.mobile-bottom-nav {
    display: none;
    position: fixed;
    bottom: 0;
    left: 0;
    width: 100%;
    height: 68px;
    background: rgba(15, 9, 31, 0.96);
